[{"order":1,"type":"heading","text":"Environment Configuration and Process Management in Express.js with PM2"},{"order":2,"type":"paragraph","text":"Building a production-ready Express.js application requires robust environment configuration and reliable process management. This tutorial covers how to securely manage environment variables using dotenv and how to keep your Node.js application running continuously using PM2."},{"order":3,"type":"subheading","text":"1. Environment Configuration with dotenv"},{"order":4,"type":"paragraph","text":"Environment variables help separate configuration from code. First, install the dotenv package in your Express project."},{"order":5,"type":"code","text":"npm install dotenv"},{"order":6,"type":"paragraph","text":"Next, create a file named .env in the root directory of your project and define your configuration variables:"},{"order":7,"type":"code","text":"PORT=3000
NODE_ENV=production
DATABASE_URL=mongodb://localhost:27017/myapp"},{"order":8,"type":"paragraph","text":"Load these variables at the very top of your entry file (e.g., server.js or app.js) before any other modules are loaded."},{"order":9,"type":"code","text":"require('dotenv').config();
const express = require('express');
const app = express();

const PORT = process.env.PORT || 3000;

app.get('/', (req, res) => {
  res.send('Environment configured successfully!');
});

app.listen(PORT, () => {
  console.log('Server running on port ' + PORT);
});"},{"order":10,"type":"subheading","text":"2. Introduction to Process Management with PM2"},{"order":11,"type":"paragraph","text":"Node.js runs on a single thread. If an uncaught exception crashes your Express app, it goes offline. PM2 is a production process manager that restarts your application automatically, manages cluster mode, and monitors system resources."},{"order":12,"type":"paragraph","text":"Install PM2 globally on your machine using npm:"},{"order":13,"type":"code","text":"npm install -g pm2"},{"order":14,"type":"subheading","text":"3. Running and Managing the Express App with PM2"},{"order":15,"type":"paragraph","text":"To start your Express application in the background using PM2, execute the following command:"},{"order":16,"type":"code","text":"pm2 start server.js --name "my-express-app""},{"order":17,"type":"bullet_point","text":"pm2 list: Displays a list of all managed processes and their status."},{"order":18,"type":"bullet_point","text":"pm2 logs: Streams real-time application logs."},{"order":19,"type":"bullet_point","text":"pm2 restart my-express-app: Restarts the application seamlessly with zero downtime."},{"order":20,"type":"bullet_point","text":"pm2 stop my-express-app: Stops the application without deleting it from PM2."},{"order":21,"type":"bullet_point","text":"pm2 delete my-express-app: Completely removes the app from PM2 tracking."},{"order":22,"type":"subheading","text":"4. Advanced Configuration using Ecosystem Files"},{"order":23,"type":"paragraph","text":"For production deployments, it is best practice to use a PM2 configuration file. Generate a sample ecosystem file using this command:"},{"order":24,"type":"code","text":"pm2 init"},{"order":25,"type":"paragraph","text":"Modify the generated ecosystem.config.js file to handle cluster mode and environment variables effectively:"},{"order":26,"type":"code","text":"module.exports = {
  apps: [
    {
      name: 'express-cluster-app',
      script: './server.js',
      instances: 'max',
      exec_mode: 'cluster',
      env: {
        NODE_ENV: 'development',
        PORT: 3000
      },
      env_production: {
        NODE_ENV: 'production',
        PORT: 8080
      }
    }
  ]
};"},{"order":27,"type":"paragraph","text":"Deploy your application using the production environment profile defined in the ecosystem file:"},{"order":28,"type":"code","text":"pm2 start ecosystem.config.js --env production"},{"order":29,"type":"subheading","text":"5. System Startup Persistence"},{"order":30,"type":"paragraph","text":"To ensure your Express application restarts automatically if the server reboots, generate and configure the startup script by running:"},{"order":31,"type":"code","text":"pm2 startup"},{"order":32,"type":"paragraph","text":"Save the current process list so PM2 knows what to resurrect upon reboot:"},{"order":33,"type":"code","text":"pm2 save"}]
